#define N 1024
int data[N];
int factor = 5;

// Temporal Locality: High reuse of 'factor'
// data loaded into registers/L1 cache once
for (int i = 0; i < 100; ++i) {
    data[0] *= factor;
}

// Spatial Locality: Sequential access exploits cache lines
// Whole cache line loaded on 'data[i]' access
for (int i = 0; i < N; ++i) {
    data[i] = i; // Unit stride: Optimal performance
}

// Poor Spatial Locality: Stride != 1 (e.g., cache ping-pong)
// Accessing every 16th element causes frequent cache misses
for (int i = 0; i < N; i += 16) {
    data[i] = 0;
}
